import {spawnSync} from "node:child_process";
import {mkdirSync,readFileSync,writeFileSync} from "node:fs";
import {createHash} from "node:crypto";
import {Admission} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/admission.ts";
const admission=new Admission({report:console.log});
async function admitted(){while(!admission.open())await new Promise(resolve=>setTimeout(resolve,2000));}
const root="/home/akisarou/Projects/nts-lanes/compiler3-memory";
const cache="/home/akisarou/.cache/nts-compiler3-memory";
const tip=spawnSync("git",["rev-parse",process.argv[2]??"HEAD"],{cwd:root,encoding:"utf8"}).stdout.trim();
const sourceDiff=spawnSync("git",["diff",tip,"--","compiler","runtime","tooling/cli","Cargo.toml","Cargo.lock"],{cwd:root,encoding:"utf8"});if(sourceDiff.status!==0||sourceDiff.stdout)throw Error("source differs from measured revision");
const generating_command=["node",import.meta.filename,...process.argv.slice(2)];
const out="/home/akisarou/.cache/nts-handover/compiler3/stage2-current/slice-final-v6-"+tip.slice(0,9);
const composedParent="ed4698fed552c465efeab1a00cee434e1b55bc3f";
const parentInputs=spawnSync("git",["diff","94f67ba65380",composedParent,"--","compiler","runtime","tooling/cli","Cargo.toml","Cargo.lock"],{cwd:root,encoding:"utf8"});if(parentInputs.status!==0||parentInputs.stdout)throw Error("official before pin does not match composed-parent build inputs");
const before_commit="94f67ba653801eb25e4a40a7cba15dbce8e5c84f";
const binaries={before:"/home/akisarou/.cache/nts-pins/94f67ba65380/nts",after:"/home/akisarou/.cache/nts-pins/"+tip.slice(0,12)+"/nts"};
const producer=JSON.parse(readFileSync("/home/akisarou/.cache/nts-pins/94f67ba65380/provenance.json","utf8"));
const dev=JSON.parse(readFileSync("/home/akisarou/.cache/nts-pins/"+tip.slice(0,12)+"/provenance.json","utf8"));
const digest=(path:string)=>createHash("sha256").update(readFileSync(path)).digest("hex");
if(producer.sha!==before_commit||!producer.clean||producer.applied!==null||producer.binary_sha256!==digest(binaries.before)||dev.sha!==tip||!dev.clean||dev.applied!==null||dev.binary_sha256!==digest(binaries.after))throw Error("unauthenticated official A/B artifact");
const cases=[
 ["json-parse",cache+"/cases/json-parse.tsconfig.json"],
 ["tree-teardown",cache+"/cases/tree-teardown.tsconfig.json"],
 ["traversal",root+"/tests/memory/traversal/tsconfig.json"],
 ["shared-tail",root+"/tests/memory/shared-tail/tsconfig.json"]
];
mkdirSync(out,{recursive:true});writeFileSync(out+"/instrument-slice.ts",readFileSync(import.meta.filename));
const hash=(s:string|Buffer)=>createHash("sha256").update(s).digest("hex");
const rows:any[]=[];
for(const [name,config] of cases)for(const backend of ["c","llvm"])for(const provider of ["nogc","rc"]){
 const stem=`${out}/${name}-${backend}-${provider}`;
 const flags=[...(provider==="rc"?["--rc"]:[]),"--entry","work","--main","--checkers","1"];
 const reports:string[]=[],reportFiles:string[]=[];
 for(let repeat=0;repeat<3;repeat++){
  await admitted();
  const argv=["regions",config,...flags,"--backend",backend];
  const r=spawnSync(binaries.after,argv,{cwd:root,encoding:"utf8",maxBuffer:128*1024*1024});
  writeFileSync(`${stem}-${repeat}.stdout`,r.stdout??"");writeFileSync(`${stem}-${repeat}.stderr`,r.stderr??"");
  if(r.error||r.status!==0||/invalid HIR/.test((r.stdout??"")+(r.stderr??"")))throw Error(`${stem}: ${r.error??r.status}`);
  const report=(r.stdout??"").split("\n").filter(line=>/^(memory-v2|work-stages|points-to-changes|memory-events|fence-context-visits|node-changes|alias-class|site|function|frontier|proof|slot|value|store-version|capture-write|retention|outcome)\t/.test(line)).join("\n")+"\n";
  if(!report.startsWith("memory-v2\t"))throw Error("missing memory report");
  if(!report.split("\n")[0].endsWith("failure=None"))throw Error("first-slice analysis did not complete: "+report.split("\n")[0]);
  const framed="# measured_commit="+tip+"\n# generating_command="+JSON.stringify(generating_command)+"\n# diagnostic_command="+JSON.stringify([binaries.after,...argv])+"\n# config_sha256="+digest(config)+"\n"+report;
  writeFileSync(`${stem}-${repeat}.memory.tsv`,framed);reports.push(report);reportFiles.push(framed);
 }
 if(new Set(reportFiles.map(hash)).size!==1)throw Error(`unstable report ${stem}`);
 const comparisons:any[]=[];
 for(const [kind,argv] of [["emit",[`emit-${backend}`,config,...flags]],["hir",["hir",config,"--prepared",...flags,"--backend",backend]],["stats",["stats",config,...flags,"--backend",backend]]] as [string,string[]][]){
  const values:any[]=[];
  for(const [arm,binary] of Object.entries(binaries)){
   await admitted();
   const r=spawnSync(binary,argv,{cwd:root,encoding:"utf8",maxBuffer:128*1024*1024});
   writeFileSync(`${stem}-${arm}-${kind}.stdout`,r.stdout??"");writeFileSync(`${stem}-${arm}-${kind}.stderr`,r.stderr??"");
   values.push({arm,status:r.status,stdout:hash(r.stdout??""),stderr:hash(r.stderr??""),bytes:Buffer.byteLength(r.stdout??""),error:r.error?.message});
  }
  const equal=values[0].status===0&&values[1].status===0&&values[0].stdout===values[1].stdout&&values[0].stderr===values[1].stderr&&!values.some(v=>v.error);
  comparisons.push({kind,equal,values});
  if(!equal)throw Error(`changed ${kind}: ${stem}`);
 }
 const sites=reports[0].split("\n").filter(l=>l.startsWith("site\t")).map(l=>l.split("\t"));
 if(sites.some(row=>row.includes("legacy=[]")))throw Error(`unmapped site ${stem}`);
 const row={name,backend,provider,report_sha256:hash(reportFiles[0]),payload_sha256:hash(reports[0]),header:reports[0].split("\n")[0],stages:reports[0].split("\n")[1],sites:sites.length,comparisons};
 rows.push(row);writeFileSync(out+"/summary.json",JSON.stringify({commit:tip,scope:"official-pin identity against binary-input-identical composed parent; diagnostic reports byte-stable across three runs; no timing claim",complete:rows.length===16,generating_command,before_commit,composed_parent:composedParent,parent_build_inputs_identical:true,before_producer:producer,after_producer:dev,binaries:Object.fromEntries(Object.entries(binaries).map(([arm,path])=>[arm,{path,sha256:hash(readFileSync(path))}])),rows},null,2)+"\n");
 console.log(JSON.stringify(row));
}

