import {spawnSync} from "node:child_process";
import {mkdirSync,readFileSync,writeFileSync,openSync,closeSync,existsSync} from "node:fs";
import {createHash} from "node:crypto";
import {Admission} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/admission.ts";
import {spawnCounted,instructionsWork} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/cputime.mjs";
import {measuredCompileEnvironment} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/canonical-environment.ts";
import {compileCommand,counterProblem,COMPILE_WORK_PROFILE,compileWorkSettings} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/compile-counter.ts";
const root="/home/akisarou/Projects/nts-lanes/compiler3-memory";
const cache="/home/akisarou/.cache/nts-handover/compiler3/stage2-current";
const tip=spawnSync("git",["rev-parse",process.argv[2]],{cwd:root,encoding:"utf8"}).stdout.trim();
const suite=process.argv[3];if(!["controls","modules"].includes(suite))throw Error("controls or modules required");
const composedParent="ed4698fed552c465efeab1a00cee434e1b55bc3f";
const parentInputs=spawnSync("git",["diff","94f67ba65380",composedParent,"--","compiler","runtime","tooling/cli","Cargo.toml","Cargo.lock"],{cwd:root,encoding:"utf8"});if(parentInputs.status!==0||parentInputs.stdout)throw Error("official before pin does not match composed-parent build inputs");
const beforeCommit="94f67ba653801eb25e4a40a7cba15dbce8e5c84f";
const sha=(value:string|Buffer)=>createHash("sha256").update(value).digest("hex");
const artifacts=Object.fromEntries([beforeCommit,tip].map((commit,at)=>{
 const folder="/home/akisarou/.cache/nts-pins/"+commit.slice(0,12),producer=JSON.parse(readFileSync(folder+"/provenance.json","utf8")),binary=folder+"/nts";
 if(producer.sha!==commit||!producer.clean||producer.applied!==null||producer.binary_sha256!==sha(readFileSync(binary)))throw Error("unbound official artifact");
 return[at?"after":"before",{commit,binary,producer}];
}));
const observer=JSON.parse(readFileSync(cache+"/allocator-observer-v6/instrumented-"+tip.slice(0,12)+".json","utf8"));
if(observer.measured_commit!==tip||observer.producer.sha!==tip||!observer.producer.applied||observer.producer.binary_sha256!==sha(readFileSync(observer.binary)))throw Error("unbound explicitly instrumented observer artifact");
const out=cache+`/cost-v6-${suite}-${tip.slice(0,9)}`;mkdirSync(out,{recursive:true});
writeFileSync(out+"/instrument.ts",readFileSync(import.meta.filename));
const environment=measuredCompileEnvironment(process.env),admission=new Admission({report:console.log});
const problem=instructionsWork();if(problem)throw Error(problem);
async function admitted(){while(!admission.open())await new Promise(resolve=>setTimeout(resolve,2000));}
function current(){const r=spawnSync("git",["rev-parse","HEAD"],{cwd:root,encoding:"utf8"});if(r.status!==0||r.stdout.trim()!==tip)throw Error("workspace revision changed during measurements");}
const controls=["calls","stores","recursive","distributed"].flatMap(family=>[16,32,64].map(n=>({id:`${family}-${n}`,family,n,provider:"rc",config:`/home/akisarou/.cache/nts-compiler3-memory/cost-inputs/${family}-${n}/tsconfig.json`})));
const modules=["runtime/web-platform","runtime/node/fs","runtime/node/http","runtime/node/process","runtime/node/zlib"].flatMap(module=>["nogc","rc"].map(provider=>({id:module.replaceAll("/","_")+"-"+provider,module,provider,config:root+"/"+module+"/tsconfig.json"})));
const entries:any[]=suite==="controls"?controls:modules,rows:any[]=[];
const median=(values:number[])=>[...values].sort((a,b)=>a-b)[1];
async function counted(id:string,arm:string,repeat:number,args:string[]){
 const binary=artifacts[arm==="diagnostic"?"after":arm].binary,file=`${out}/${id}-${arm}-${repeat}.json`;
 let row:any;
 if(existsSync(file)){
  const saved=JSON.parse(readFileSync(file,"utf8"));if(saved.measured_commit!==tip||saved.binary_sha256!==sha(readFileSync(binary))||JSON.stringify(saved.command)!==JSON.stringify([binary,...args]))throw Error("stale counter checkpoint");row=saved.row;
 }else{
  await admitted();const fd=openSync(`${out}/${id}-${arm}-${repeat}.stderr`,"w");
  const launch=spawnCounted(binary,args,{cwd:root,env:environment,stdio:["ignore","ignore",fd],counterFile:`${out}/${id}-${arm}-${repeat}.perf`});
  row=await launch.measurement;closeSync(fd);
  if(row.status!==0||row.signal||row.error||row.counter_error||!Number.isSafeInteger(row.instructions)||row.instructions<=0||counterProblem(row))throw Error("invalid counter "+JSON.stringify(row));
  writeFileSync(file,JSON.stringify({measured_commit:tip,binary_sha256:sha(readFileSync(binary)),command:[binary,...args],row},null,2)+"\n");
 }
 if(row.status!==0||row.signal||row.error||row.counter_error||!Number.isSafeInteger(row.instructions)||row.instructions<=0||counterProblem(row))throw Error("invalid retained counter");
 return {arm,repeat,...row};
}
async function bracket(entry:any,args:string[],kind:"bytes"|"cpu",reference?:string){
 await admitted();const file=`${out}/${entry.id}-${kind}.json`,base=cache+"/allocator-observer-v6";
 const env={...environment,COMPILER3_OBSERVER_TOOLS:base,...(kind==="bytes"?{COMPILER3_COUNTER_JSON:file}:{COMPILER3_CPU_JSON:file})};
 const binary=kind==="bytes"?observer.binary:artifacts.after.binary;
 const command=["gdb","--batch","--nx","-q","-x",base+(kind==="bytes"?"/measure.gdb":"/cpu.gdb"),"--args",binary,...args];
 const stdout=openSync(`${out}/${entry.id}-${kind}.stdout`,"w"),stderr=openSync(`${out}/${entry.id}-${kind}.stderr`,"w");
 const r=spawnSync(command[0],command.slice(1),{cwd:root,env,stdio:["ignore",stdout,stderr]});closeSync(stdout);closeSync(stderr);
 if(r.status!==0||r.signal||r.error||!existsSync(file))throw Error("invalid bracket process "+entry.id+" "+kind);
 const result=JSON.parse(readFileSync(file,"utf8"));
 if(result.inferior_exit_code!==0||result.signal||result.errors.length||result.phases.length!==1||result.symbol_identity.binary_sha256!==sha(readFileSync(binary)))throw Error("invalid bracket "+JSON.stringify(result));
 const phase=result.phases[0];if(JSON.stringify(phase.entry_thread)!==JSON.stringify(phase.return_thread))throw Error("phase switched thread");
 if(kind==="bytes"&&(phase.failed||phase.peak_requested_bytes<=0)||kind==="cpu"&&(phase.cpu_ns<=0||result.process_cpu.total_s<=0))throw Error("invalid phase column");
 return {command,raw_file:file,raw_sha256:sha(readFileSync(file)),...result};
}
for(const entry of entries){
 current();const normal=suite==="modules"?compileCommand(entry.provider,entry.config):["hir",entry.config,"--prepared","--rc","--entry","work","--main","--checkers","1","--backend","c"];
 const diagnostic=["regions",...normal.slice(1).filter(arg=>arg!=="--prepared")],runs:any[]=[];
 for(let repeat=0;repeat<3;repeat++)for(const arm of ["before","after"])runs.push(await counted(entry.id,arm,repeat,normal));
 for(let repeat=0;repeat<3;repeat++)runs.push(await counted(entry.id,"diagnostic",repeat,diagnostic));
 const bytes=await bracket(entry,diagnostic,"bytes");
 const cpu=await bracket(entry,diagnostic,"cpu",bytes.raw_file);
 const text=readFileSync(`${out}/${entry.id}-bytes.stdout`,"utf8");
 const header=text.split("\n").find(line=>line.startsWith("memory-v2\t"));
 const points=text.split("\n").find(line=>line.startsWith("points-to-changes\t"));
 const events=text.split("\n").find(line=>line.startsWith("memory-events\t"));
 if(!header||!points||!events)throw Error("missing report columns");
 const completed=header.endsWith("failure=None");if(suite==="controls"&&!completed)throw Error("control did not finish: "+header);
 const medians=Object.fromEntries(["before","after","diagnostic"].map(arm=>[arm,{instructions:median(runs.filter(r=>r.arm===arm).map(r=>r.instructions)),cpu_s:median(runs.filter(r=>r.arm===arm).map(r=>r.cpu_s))}]));
 rows.push({...entry,normal_command:normal,diagnostic_command:diagnostic,runs,medians,ordinary_instruction_ratio:medians.after.instructions/medians.before.instructions,
  diagnostic_command_instruction_ratio:medians.diagnostic.instructions/medians.after.instructions,
  analysis:{header,completed,work:Number(/work=(\d+)\//.exec(header)![1]),points,events},executing_thread_bytes:bytes,executing_thread_cpu:cpu,
  diagnostic_thread_cpu_share:cpu.phases[0].cpu_ns/(1e9*cpu.process_cpu.total_s),instrument_thread_cpu_ratio:bytes.phases[0].instrumented_thread_cpu_ns/cpu.phases[0].cpu_ns,instrument_command_cpu_ratio:bytes.process_cpu.total_s/cpu.process_cpu.total_s});
 const source=readFileSync(import.meta.filename,"utf8");
 writeFileSync(out+"/summary.json",JSON.stringify({measured_commit:tip,baseline_commit:beforeCommit,composed_parent:composedParent,parent_build_inputs_identical:true,generating_command:[process.execPath,import.meta.filename,...process.argv.slice(2)],suite,artifacts,observer,work_profile:COMPILE_WORK_PROFILE,work_settings:compileWorkSettings(environment),
  scope:"Ordinary preparation and explicit regions diagnostic command measured separately; diagnostic rendering is included in command deltas, not mislabelled solver work. CPU body probe has no allocator interposer. Byte probe uses an explicitly instrumented allocator-only CLI and reports selected-thread Rust requested payload, with epoch header/padding excluded separately; ordinary instructions and the CPU bracket use the untouched formal CLI.",
  instrument:{sha256:sha(source),source},rows},null,2)+"\n");
 console.log(JSON.stringify({id:entry.id,work:rows.at(-1).analysis.work,completed,ordinary_ratio:rows.at(-1).ordinary_instruction_ratio,peak_bytes:bytes.phases[0].peak_requested_bytes}));
}

