import {gzipSync} from "node:zlib";
import {spawnSync} from "node:child_process";
import {mkdirSync,readFileSync,writeFileSync,appendFileSync,copyFileSync,chmodSync,existsSync,readdirSync,rmSync,openSync,closeSync} from "node:fs";
import {createHash} from "node:crypto";
import {join,relative,extname} from "node:path";
import {Admission} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/admission.ts";
const root="/home/akisarou/Projects/nts-lanes/compiler3-memory",cache="/home/akisarou/.cache/nts-handover/compiler3/stage2-current";
const tip=process.argv[2],baseline=process.argv[3],before=process.argv[4];
if(!tip||!baseline||!before)throw Error("source revision, baseline revision and baseline compiler required");
const command=["node",import.meta.filename,...process.argv.slice(2)],hash=(v:string|Buffer)=>createHash("sha256").update(v).digest("hex");
const clean=spawnSync("git",["diff",tip,"--","compiler","runtime","tooling/cli","Cargo.toml","Cargo.lock"],{cwd:root,encoding:"utf8"});
if(clean.status!==0||clean.stdout)throw Error("source differs from measured revision");
const after="/home/akisarou/.cache/nts-pins/"+tip.slice(0,12)+"/nts";
const official=JSON.parse(readFileSync(after.replace(/nts$/, "provenance.json"),"utf8"));
const prior=JSON.parse(readFileSync(before.replace(/nts$/, "provenance.json"),"utf8"));
if(official.sha!==tip||!official.clean||official.applied!==null||official.binary_sha256!==hash(readFileSync(after)))throw Error("unbound candidate formal pin");
if(prior.sha!==baseline||!prior.clean||prior.applied!==null||prior.binary_sha256!==hash(readFileSync(before)))throw Error("unbound parent formal pin");
const parent="ed4698fed552c465efeab1a00cee434e1b55bc3f";
const parentInputs=spawnSync("git",["diff",baseline,parent,"--","compiler","runtime","tooling/cli","Cargo.toml","Cargo.lock"],{cwd:root,encoding:"utf8"});if(parentInputs.status!==0||parentInputs.stdout)throw Error("parent compiler inputs differ from official before pin");
const work=`${cache}/corpus-v6-${tip.slice(0,9)}`;mkdirSync(work,{recursive:true});
const bins=Object.fromEntries(Object.entries({before,after}).map(([arm,path])=>{
 const sha256=hash(readFileSync(path)),dir=cache+"/bin/"+sha256,pinned=dir+"/nts";mkdirSync(dir,{recursive:true});
 if(!existsSync(pinned))copyFileSync(path,pinned);
 chmodSync(pinned,0o755);if(hash(readFileSync(pinned))!==sha256)throw Error("bad pinned compiler");
 return[arm,{path,pinned,sha256,commit:arm==="before"?baseline:tip}];
}));
if(bins.before.sha256===bins.after.sha256)throw Error("vacuous identical-compiler comparison");
type Project={group:string,name:string,config:string,input_sha256:string,source?:string};
const projects:Project[]=[],skipped:any[]=[];
const manifestFile=root+"/tooling/suite/corpus-core.json",manifest=JSON.parse(readFileSync(manifestFile,"utf8"));
if(!Array.isArray(manifest)||manifest.length===0||new Set(manifest).size!==manifest.length)throw Error("invalid core corpus manifest");
for(const name of manifest){
 const source="third_party/typescript/tsc/testdata/tests/cases/"+name,bytes=readFileSync(root+"/"+source);
 if(bytes.includes(Buffer.from("@filename"))){skipped.push({group:"typescript-core",name,source,input_sha256:hash(bytes),reason:"the corpus's raw-byte multi-file filter"});continue;}
 const id=hash(name).slice(0,16),dir=work+"/inputs/corpus-"+id,src=dir+"/src";mkdirSync(src,{recursive:true});
 const target=src+"/main"+(extname(name)===".tsx"?".tsx":".ts");copyFileSync(root+"/"+source,target);
 const config=dir+"/tsconfig.json";writeFileSync(config,JSON.stringify({compilerOptions:{target:"ESNext",module:"ESNext",moduleResolution:"bundler",strict:true,noEmit:true},include:["src"]},null,2)+"\n");
 projects.push({group:"typescript-core",name,config,input_sha256:hash(bytes),source});
}
projects.sort((a,b)=>(a.group+"/"+a.name).localeCompare(b.group+"/"+b.name,"en"));
const admission=new Admission({report:console.log}),rows:any[]=[];
writeFileSync(work+"/rows.jsonl","");
function inventory(dir:string):any[]{
 if(!existsSync(dir))return[];
 const found:any[]=[];
 function visit(at:string){for(const entry of readdirSync(at,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name,"en"))){const path=join(at,entry.name);if(entry.isDirectory())visit(path);else if(entry.isFile()){const bytes=readFileSync(path);found.push({file:relative(dir,path),bytes:bytes.length,sha256:hash(bytes)});}}}
 visit(dir);return found;
}
function retainedWitness(dir:string,stem:string,listing:string):any{
 const saved:any[]=[],definitions:string[]=[];
 for(const item of inventory(dir)){
  const data=readFileSync(join(dir,item.file)),target=stem+".bodies/"+item.file+".gz";
  mkdirSync(join(target,".."),{recursive:true});writeFileSync(target,gzipSync(data));saved.push({...item,path:target,compressed_sha256:hash(readFileSync(target))});
  if(item.file.endsWith(".c"))for(const match of data.toString().matchAll(/^[^\s#][^;{}\n]*?\b([A-Za-z_][A-Za-z_0-9]*)\([^;{}\n]*\)\s*\{/gm))definitions.push(match[1]);
 }
 const names=[...new Set(definitions)].sort(),headers=listing.split("\n").filter(line=>/^(?:export )?(?:declare )?func /.test(line));
 const expected=headers.flatMap(line=>{const m=/^export func ([A-Za-z_][A-Za-z_0-9]*)\(/.exec(line);return m?[m[1]]:[];});
 return{scope:"Actual bodies retained compressed; prepared headers and exact simple-export matches retained. Mangled/unmatched expectations are explicit.",artifacts:saved,definitions:names,prepared_headers:headers,simple_export_expectations:expected.map(name=>({name,actual_definition:names.includes(name)}))};
}
for(const project of projects)for(const provider of ["nogc","rc"]){
 const id=hash(project.group+"/"+project.name+"/"+provider).slice(0,16),out=work+"/out",arms:any[]=[];
 for(const [arm,binary] of Object.entries(bins)){
  while(!admission.open())await new Promise(resolve=>setTimeout(resolve,2000));
  rmSync(out,{recursive:true,force:true});mkdirSync(out,{recursive:true});
  const stdout=work+`/${id}-${arm}.stdout`,stderr=work+`/${id}-${arm}.stderr`,o=openSync(stdout,"w"),e=openSync(stderr,"w");
  const args=["emit-c",project.config,"--out",out,"--checkers","1",...(provider==="rc"?["--rc"]:[])];
  const r=spawnSync(binary.pinned,args,{cwd:root,env:process.env,stdio:["ignore",o,e]});closeSync(o);closeSync(e);
  const errors=readFileSync(stderr),output=readFileSync(stdout),artifacts=inventory(out);
  const listingOut=work+`/${id}-${arm}-hir.stdout`,listingErr=work+`/${id}-${arm}-hir.stderr`,lo=openSync(listingOut,"w"),le=openSync(listingErr,"w");
  const listingArgs=["hir",project.config,"--prepared","--backend","c","--checkers","1",...(provider==="rc"?["--rc"]:[])];
  const lr=spawnSync(binary.pinned,listingArgs,{cwd:root,env:process.env,stdio:["ignore",lo,le]});closeSync(lo);closeSync(le);
  const listing={command:[binary.pinned,...listingArgs],status:lr.status,signal:lr.signal,stdout:listingOut,stderr:listingErr,stdout_sha256:hash(readFileSync(listingOut)),stderr_sha256:hash(readFileSync(listingErr))};
  const emitted_witness=retainedWitness(out,work+`/${id}-${arm}`,readFileSync(listingOut,"utf8"));
  arms.push({arm,emitted_witness,prepared_listing:listing,command:[binary.pinned,...args],status:r.status,signal:r.signal,error:r.error?.message,stdout_sha256:hash(output),stderr_sha256:hash(errors),artifacts,has_c:artifacts.some(row=>row.file==="program.c"&&row.bytes>0),diagnostic:errors.toString("utf8").slice(0,2000)});
 }
