files = {}
def bind(path, contents=False):
    path = Path(path).resolve()
    if str(path) in files: return
    data = path.read_bytes()
    item = dict(path=str(path), bytes=len(data), sha256=hashlib.sha256(data).hexdigest())
    if path.is_relative_to(root):
        relative = str(path.relative_to(root))
        expected = subprocess.check_output(['git','show',measured+':'+relative],cwd=root)
        assert data == expected, relative+' changed from measured revision'
        frozen=cache/('frozen-replay-source-'+measured[:12])/relative
        frozen.parent.mkdir(parents=True,exist_ok=True)
        if frozen.exists():assert frozen.read_bytes()==data
        else:frozen.write_bytes(data)
        item.update(path=str(frozen),observed_path=str(path),repository_path=relative,repository_commit=measured)
    if contents:
        try:item['source'] = data.decode('utf8')
        except UnicodeDecodeError:
            item['source_encoding']='base64'
            item['source_base64']=base64.b64encode(data).decode('ascii')
    files[str(path)] = item

