bind(artifact['link_handoff']['library'])
bind(artifact['binary'])
bind(observer/'transparent-counter.so')
for name in ['counter.c','cpu.gdb','cpu-validation.json','rust-cpu-control.json','rust-cpu-control.log','validate-cpu.py']:
