queue = [root/'tooling/gate'/name for name in ['cputime.mjs','compile-counter.ts',
    'canonical-environment.ts','admission.ts']]
seen = set()
while queue:
    path = queue.pop().resolve()
    if path in seen: continue
    seen.add(path);bind(path, True)
    for imported in re.findall(r'(?:from\s*|import\s*)["\'](\.[^"\']+)["\']', path.read_text()):
