import {createReadStream} from "node:fs";
import {createInterface} from "node:readline";

export async function readReportMetadata(path) {
  const stream = createReadStream(path, {highWaterMark: 8192});
  const lines = createInterface({input: stream, crlfDelay: Infinity});
  const found = {};
  try {
    for await (const line of lines) {
      for (const [key, prefix] of [["header", "memory-v2\t"], ["points", "points-to-changes\t"], ["events", "memory-events\t"]]) {
        if (found[key] === undefined && line.startsWith(prefix)) found[key] = line;
      }
      if (found.header !== undefined && found.points !== undefined && found.events !== undefined) break;
    }
  } finally {
    lines.close();
    stream.destroy();
  }
  if (found.header === undefined || found.points === undefined || found.events === undefined) throw Error("missing report columns");
  return found;
}

