use super::*;
use std::ptr;
const OBSERVER: Observer = Observer::system();
fn v(field: u64) -> u64 {
    nts_counter_value(field)
}

#[test]
fn requested_alignment_zeroed_payload_and_base_recovery() {
    for align in [1, 2, 8, 16, 64, 4096] {
        let layout = Layout::from_size_align(37, align).unwrap();
        assert_eq!(nts_counter_begin(), 0);
        let p = unsafe { OBSERVER.alloc_zeroed(layout) };
        assert!(!p.is_null());
        assert_eq!(p as usize % align, 0);
        assert!(
            unsafe { std::slice::from_raw_parts(p, 37) }
                .iter()
                .all(|b| *b == 0)
        );
        assert_eq!(v(0), 37);
        assert_eq!(v(7), expanded(layout).unwrap().1 as u64);
        unsafe { OBSERVER.dealloc(p, layout) };
        assert_eq!(nts_counter_end(), 0);
        assert_eq!(v(0), 0);
        assert_eq!(v(4), 0);
        assert_eq!(v(1), 37);
        assert_eq!(v(5), 1);
    }
}
#[test]
fn prephase_and_prior_epoch_frees_are_excluded() {
    let layout = Layout::from_size_align(32, 8).unwrap();
    let before = unsafe { OBSERVER.alloc(layout) };
    assert_eq!(nts_counter_begin(), 0);
    unsafe { OBSERVER.dealloc(before, layout) };
    let survivor = unsafe { OBSERVER.alloc(layout) };
    assert_eq!(nts_counter_end(), 0);
    assert_eq!(v(0), 32);
    let old_epoch = v(13);
    assert_eq!(nts_counter_begin(), 0);
    assert!(v(13) > old_epoch);
    unsafe { OBSERVER.dealloc(survivor, layout) };
    assert_eq!(nts_counter_end(), 0);
    assert_eq!(v(0), 0);
    assert_eq!(v(6), 0);
}
#[test]
fn moved_and_aligned_realloc_count_old_out_and_new_in() {
    for align in [8, 64, 4096] {
        let old = Layout::from_size_align(16, align).unwrap();
        assert_eq!(nts_counter_begin(), 0);
        let p = unsafe { OBSERVER.alloc(old) };
        assert!(!p.is_null());
        unsafe { ptr::write_bytes(p, 0x5a, 16) };
        let q = unsafe { OBSERVER.realloc(p, old, 8192) };
        assert!(!q.is_null());
        assert_eq!(q as usize % align, 0);
        assert!(
            unsafe { std::slice::from_raw_parts(q, 16) }
                .iter()
                .all(|b| *b == 0x5a)
        );
        assert_eq!(v(0), 8192);
        assert_eq!(v(1), 8192);
        assert_eq!(v(2), 8208);
        assert_eq!(v(3), 2);
        assert_eq!(v(4), 1);
        assert_eq!(v(6), 1);
        let grown = Layout::from_size_align(8192, align).unwrap();
        let r = unsafe { OBSERVER.realloc(q, grown, 8) };
        assert!(!r.is_null());
        assert_eq!(v(0), 8);
        assert_eq!(v(1), 8192);
        assert_eq!(v(3), 3);
        assert_eq!(v(6), 2);
        unsafe { OBSERVER.dealloc(r, Layout::from_size_align(8, align).unwrap()) };
        assert_eq!(nts_counter_end(), 0);
        assert_eq!(v(0), 0);
    }
}
struct InPlace;
unsafe impl GlobalAlloc for InPlace {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        unsafe { System.alloc(Layout::from_size_align(65536, l.align()).unwrap()) }
    }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        unsafe { System.dealloc(p, Layout::from_size_align(65536, l.align()).unwrap()) }
    }
    unsafe fn realloc(&self, p: *mut u8, _: Layout, n: usize) -> *mut u8 {
        if n <= 65536 { p } else { ptr::null_mut() }
    }
}
#[test]
fn in_place_growth_and_failed_realloc_preserve_accounting() {
    let observer = Observer(InPlace);
    let l = Layout::from_size_align(16, 64).unwrap();
    assert_eq!(nts_counter_begin(), 0);
    let p = unsafe { observer.alloc(l) };
    assert!(!p.is_null());
    unsafe { ptr::write_bytes(p, 42, 16) };
    let q = unsafe { observer.realloc(p, l, 32) };
    assert_eq!(p, q);
    assert_eq!(v(0), 32);
    assert_eq!(v(1), 32);
    assert_eq!(v(4), 1);
    let grown = Layout::from_size_align(32, 64).unwrap();
    let saved = (v(0), v(1), v(2), v(3), v(4), v(6), v(12));
    assert!(unsafe { observer.realloc(q, grown, 65536) }.is_null());
    assert_eq!((v(0), v(1), v(2), v(3), v(4), v(6), v(12)), saved);
    assert!(
        unsafe { std::slice::from_raw_parts(q, 16) }
            .iter()
            .all(|b| *b == 42)
    );
    unsafe { observer.dealloc(q, grown) };
    assert_eq!(nts_counter_end(), 0);
    assert_eq!(v(0), 0);
}
#[test]
fn realloc_of_preexisting_storage_starts_a_new_counted_lifetime() {
    let old = Layout::from_size_align(16, 8).unwrap();
    let p = unsafe { OBSERVER.alloc(old) };
    assert_eq!(nts_counter_begin(), 0);
    let q = unsafe { OBSERVER.realloc(p, old, 128) };
    assert!(!q.is_null());
    assert_eq!(v(0), 128);
    assert_eq!(v(6), 0);
    assert_eq!(v(3), 1);
    unsafe { OBSERVER.dealloc(q, Layout::from_size_align(128, 8).unwrap()) };
    assert_eq!(nts_counter_end(), 0);
    assert_eq!(v(0), 0);
}
#[test]
fn many_simultaneously_live_allocations_have_no_registry_capacity() {
    // More live entries than the rejected 2^22-entry pointer registry.
    let n = (1 << 22) + 1;
    let layout = Layout::from_size_align(1, 1).unwrap();
    let mut pointers = Vec::with_capacity(n);
    assert_eq!(nts_counter_begin(), 0);
    for _ in 0..n {
        let p = unsafe { OBSERVER.alloc(layout) };
        assert!(!p.is_null());
        pointers.push(p);
    }
    assert_eq!(v(0), n as u64);
    assert_eq!(v(4), n as u64);
    for p in pointers {
        unsafe { OBSERVER.dealloc(p, layout) };
    }
    assert_eq!(nts_counter_end(), 0);
    assert_eq!(v(1), n as u64);
    assert_eq!(v(0), 0);
}
#[test]
fn nested_wrong_thread_and_cross_thread_release_fail_closed() {
    assert_eq!(nts_counter_begin(), 0);
    assert_ne!(nts_counter_begin(), 0);
    assert_ne!(nts_counter_end(), 0);
    assert_eq!(nts_counter_begin(), 0);
    assert_ne!(std::thread::spawn(|| nts_counter_end()).join().unwrap(), 0);
    assert_ne!(nts_counter_end(), 0);
    let l = Layout::from_size_align(32, 8).unwrap();
    assert_eq!(nts_counter_begin(), 0);
    let p = unsafe { OBSERVER.alloc(l) } as usize;
    std::thread::spawn(move || unsafe { OBSERVER.dealloc(p as *mut u8, l) })
        .join()
        .unwrap();
    assert_ne!(nts_counter_end(), 0);
    assert_ne!(v(14) & CROSS_THREAD_FREE, 0);
}
#[test]
fn impossible_expansion_is_rejected_without_changing_live_state() {
    let l = Layout::from_size_align(32, 8).unwrap();
    assert_eq!(nts_counter_begin(), 0);
    let p = unsafe { OBSERVER.alloc(l) };
    assert!(unsafe { OBSERVER.realloc(p, l, usize::MAX) }.is_null());
    assert_eq!(v(0), 32);
    unsafe { OBSERVER.dealloc(p, l) };
    assert_eq!(nts_counter_end(), 0);
}
#[test]
fn accounting_overflow_marks_the_measurement_invalid() {
    assert_eq!(nts_counter_begin(), 0);
    COUNTS.with(|cell| {
        let mut c = cell.get();
        c.live = u64::MAX;
        cell.set(c)
    });
    let l = Layout::from_size_align(1, 1).unwrap();
    let p = unsafe { OBSERVER.alloc(l) };
    unsafe { OBSERVER.dealloc(p, l) };
    assert_ne!(nts_counter_end(), 0);
}
unsafe extern "C" {
    fn malloc(size: usize) -> *mut std::ffi::c_void;
    fn free(ptr: *mut std::ffi::c_void);
    fn strlen(ptr: *const i8) -> usize;
}
#[test]
fn foreign_allocations_stay_foreign_and_rust_borrows_keep_their_header() {
    assert_eq!(nts_counter_begin(), 0);
    let foreign = unsafe { malloc(91) };
    assert!(!foreign.is_null());
    unsafe { free(foreign) };
    assert_eq!(v(3), 0);
    assert_eq!(v(0), 0);
    let l = Layout::from_size_align(4, 1).unwrap();
    let p = unsafe { OBSERVER.alloc(l) };
    unsafe { ptr::copy_nonoverlapping(b"abc\0".as_ptr(), p, 4) };
    assert_eq!(unsafe { strlen(p.cast()) }, 3);
    unsafe { OBSERVER.dealloc(p, l) };
    assert_eq!(nts_counter_end(), 0);
    assert_eq!(v(1), 4);
}

