//! Measurement-only Rust allocator. No pointer registry or fixed live capacity.
use std::alloc::{GlobalAlloc, Layout, System};
use std::cell::Cell;
use std::sync::atomic::{AtomicU64, Ordering};

#[repr(C)]
struct Header {
    epoch: u64,
}
const INITIAL_HASH: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x100_0000_01b3;
const NESTED: u64 = 1;
const ACCOUNTING: u64 = 2;
const CROSS_THREAD_FREE: u64 = 4;
const WRONG_THREAD: u64 = 8;
static NEXT_EPOCH: AtomicU64 = AtomicU64::new(1);
static ACTIVE_EPOCH: AtomicU64 = AtomicU64::new(0);
static FAILURE: AtomicU64 = AtomicU64::new(0);

#[derive(Clone, Copy)]
struct Counts {
    epoch: u64,
    active: bool,
    live: u64,
    peak: u64,
    total: u64,
    entries: u64,
    peak_entries: u64,
    allocations: u64,
    frees: u64,
    header_live: u64,
    header_peak: u64,
    header_total: u64,
    combined_peak: u64,
    max_align: u64,
    trace: u64,
}
impl Counts {
    const fn empty() -> Self {
        Self {
            epoch: 0,
            active: false,
            live: 0,
            peak: 0,
            total: 0,
            entries: 0,
            peak_entries: 0,
            allocations: 0,
            frees: 0,
            header_live: 0,
            header_peak: 0,
            header_total: 0,
            combined_peak: 0,
            max_align: 0,
            trace: INITIAL_HASH,
        }
    }
    fn hash(&mut self, kind: u64, size: usize) {
        // Hash logical allocation/free events only. Addresses and the
        // observer's header never enter the program's allocation trace.
        for word in [kind, size as u64] {
            for byte in word.to_le_bytes() {
                self.trace = (self.trace ^ u64::from(byte)).wrapping_mul(FNV_PRIME);
            }
        }
    }
    fn add(&mut self, size: usize, padding: usize, align: usize) {
        let Some((live, total, entries, allocations, header_live, header_total)) = self
            .live
            .checked_add(size as u64)
            .zip(self.total.checked_add(size as u64))
            .zip(self.entries.checked_add(1))
            .zip(self.allocations.checked_add(1))
            .zip(self.header_live.checked_add(padding as u64))
            .zip(self.header_total.checked_add(padding as u64))
            .map(|(((((a, b), c), d), e), f)| (a, b, c, d, e, f))
        else {
            FAILURE.fetch_or(ACCOUNTING, Ordering::Relaxed);
            return;
        };
        let Some(combined) = live.checked_add(header_live) else {
            FAILURE.fetch_or(ACCOUNTING, Ordering::Relaxed);
            return;
        };
        self.live = live;
        self.total = total;
        self.entries = entries;
        self.allocations = allocations;
        self.header_live = header_live;
        self.header_total = header_total;
        self.peak = self.peak.max(live);
        self.peak_entries = self.peak_entries.max(entries);
        self.header_peak = self.header_peak.max(header_live);
        self.combined_peak = self.combined_peak.max(combined);
        self.max_align = self.max_align.max(align as u64);
        self.hash(1, size);
    }
    fn remove(&mut self, size: usize, padding: usize) {
        let Some((live, header_live, entries, frees)) = self
            .live
            .checked_sub(size as u64)
            .zip(self.header_live.checked_sub(padding as u64))
            .zip(self.entries.checked_sub(1))
            .zip(self.frees.checked_add(1))
            .map(|(((a, b), c), d)| (a, b, c, d))
        else {
            FAILURE.fetch_or(ACCOUNTING, Ordering::Relaxed);
            return;
        };
        self.live = live;
        self.header_live = header_live;
        self.entries = entries;
        self.frees = frees;
        self.hash(2, size);
    }
}
thread_local! { static COUNTS: Cell<Counts> = const {Cell::new(Counts::empty())}; }

/// Header padding is at least both the requested alignment and header size,
/// rounded to the requested alignment. The expanded base also aligns Header.
fn expanded(layout: Layout) -> Option<(Layout, usize)> {
    let align = layout.align();
    let offset = align
        .max(std::mem::size_of::<Header>())
        .checked_add(align - 1)?
        & !(align - 1);
    let size = layout.size().checked_add(offset)?;
    let base = Layout::from_size_align(size, align.max(std::mem::align_of::<Header>())).ok()?;
    Some((base, offset))
}

fn allocated(size: usize, padding: usize, align: usize) -> u64 {
    COUNTS
        .try_with(|cell| {
            let mut c = cell.get();
            if !c.active {
                return 0;
            }
            c.add(size, padding, align);
            let epoch = c.epoch;
            cell.set(c);
            epoch
        })
        .unwrap_or(0)
}
fn removed(epoch: u64, size: usize, padding: usize) {
    if epoch == 0 {
        return;
    }
    let own = COUNTS
        .try_with(|cell| {
            let mut c = cell.get();
            if !c.active || c.epoch != epoch {
                return false;
            }
            c.remove(size, padding);
            cell.set(c);
            true
        })
        .unwrap_or(false);
    if !own && ACTIVE_EPOCH.load(Ordering::Acquire) == epoch {
        // This observer is scoped to a synchronous executing-thread phase.
        // A cross-thread release invalidates it instead of inventing a peak.
        FAILURE.fetch_or(CROSS_THREAD_FREE, Ordering::Relaxed);
    }
}

pub struct Observer<A: GlobalAlloc = System>(pub A);
impl Observer<System> {
    pub const fn system() -> Self {
        Self(System)
    }
}
unsafe impl<A: GlobalAlloc> GlobalAlloc for Observer<A> {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let Some((base_layout, offset)) = expanded(layout) else {
            return std::ptr::null_mut();
        };
        let base = unsafe { self.0.alloc(base_layout) };
        if base.is_null() {
            return base;
        }
        let payload = unsafe { base.add(offset) };
        let epoch = allocated(layout.size(), offset, layout.align());
        unsafe {
            payload
                .sub(std::mem::size_of::<Header>())
                .cast::<Header>()
                .write(Header { epoch });
        }
        payload
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        let Some((base_layout, offset)) = expanded(layout) else {
            return std::ptr::null_mut();
        };
        let base = unsafe { self.0.alloc_zeroed(base_layout) };
        if base.is_null() {
            return base;
        }
        let payload = unsafe { base.add(offset) };
        let epoch = allocated(layout.size(), offset, layout.align());
        unsafe {
            payload
                .sub(std::mem::size_of::<Header>())
                .cast::<Header>()
                .write(Header { epoch });
        }
        payload
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        let Some((base_layout, offset)) = expanded(layout) else {
            std::process::abort();
        };
        let epoch = unsafe {
            ptr.sub(std::mem::size_of::<Header>())
                .cast::<Header>()
                .read()
                .epoch
        };
        removed(epoch, layout.size(), offset);
        unsafe {
            self.0.dealloc(ptr.sub(offset), base_layout);
        }
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        let Some((base_layout, offset)) = expanded(layout) else {
            std::process::abort();
        };
        let Some(expanded_size) = new_size.checked_add(offset) else {
            return std::ptr::null_mut();
        };
        if Layout::from_size_align(expanded_size, base_layout.align()).is_err() {
            return std::ptr::null_mut();
        }
        let epoch = unsafe {
            ptr.sub(std::mem::size_of::<Header>())
                .cast::<Header>()
                .read()
                .epoch
        };
        let base = unsafe { self.0.realloc(ptr.sub(offset), base_layout, expanded_size) };
        // Failure preserves the original allocation, header and accounting.
        if base.is_null() {
            return base;
        }
        removed(epoch, layout.size(), offset);
        let payload = unsafe { base.add(offset) };
        let epoch = allocated(new_size, offset, layout.align());
        unsafe {
            payload
                .sub(std::mem::size_of::<Header>())
                .cast::<Header>()
                .write(Header { epoch });
        }
        payload
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn nts_counter_begin() -> u64 {
    let epoch =
        match NEXT_EPOCH.try_update(Ordering::Relaxed, Ordering::Relaxed, |n| n.checked_add(1)) {
            Ok(epoch) => epoch,
            Err(_) => {
                FAILURE.fetch_or(ACCOUNTING, Ordering::Relaxed);
                return 1;
            }
        };
    if ACTIVE_EPOCH
        .compare_exchange(0, epoch, Ordering::AcqRel, Ordering::Acquire)
        .is_err()
    {
        FAILURE.fetch_or(NESTED, Ordering::Relaxed);
        return 1;
    }
    FAILURE.store(0, Ordering::Relaxed);
    COUNTS.with(|cell| {
        let mut c = Counts::empty();
        c.epoch = epoch;
        c.active = true;
        cell.set(c);
    });
    0
}
#[unsafe(no_mangle)]
pub extern "C" fn nts_counter_end() -> u64 {
    let mut c = COUNTS.with(Cell::get);
    if !c.active || ACTIVE_EPOCH.load(Ordering::Acquire) != c.epoch {
        FAILURE.fetch_or(WRONG_THREAD, Ordering::Relaxed);
        return FAILURE.load(Ordering::Relaxed);
    }
    c.active = false;
    COUNTS.with(|cell| cell.set(c));
    ACTIVE_EPOCH.store(0, Ordering::Release);
    FAILURE.load(Ordering::Relaxed)
}
#[unsafe(no_mangle)]
pub extern "C" fn nts_counter_value(field: u64) -> u64 {
    let c = COUNTS.with(Cell::get);
    match field {
        0 => c.live,
        1 => c.peak,
        2 => c.total,
        3 => c.allocations,
        4 => c.entries,
        5 => c.peak_entries,
        6 => c.frees,
        7 => c.header_live,
        8 => c.header_peak,
        9 => c.header_total,
        10 => c.combined_peak,
        11 => c.max_align,
        12 => c.trace,
        13 => c.epoch,
        14 => FAILURE.load(Ordering::Relaxed),
        _ => u64::MAX,
    }
}
pub fn keep_symbols() {
    std::hint::black_box(nts_counter_begin as extern "C" fn() -> u64);
    std::hint::black_box(nts_counter_end as extern "C" fn() -> u64);
    std::hint::black_box(nts_counter_value as extern "C" fn(u64) -> u64);
}

