mod hir {pub mod memory {
    pub struct Analysis;
    impl Analysis {
        #[inline(never)]
        pub fn with_limits()->Vec<u8> {
            let mut payload=Vec::with_capacity(32);
            for n in 0..32 {payload.push(n);}
            std::hint::black_box(payload)
        }
    }
}}
fn main() {
    let report=hir::memory::Analysis::with_limits();
    assert_eq!(report.len(),32);assert_eq!(report[31],31);
    println!("retained report {}",report.len());
}

