/* Measurement-only fixed-capacity requested-byte registry. An indexed AVL
 * stores only live allocations; freed indices return immediately to its free
 * list. Capacity is unchanged (2^22 live entries). The zero index is a sentinel.
 * AVL minimum-node growth bounds its height well below 64 at this capacity;
 * the explicit depth guard still invalidates any corrupt/unbalanced result.
 * Requested peaks exclude this registry and allocator bookkeeping. */
#define _GNU_SOURCE
#include <errno.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <sys/mman.h>

extern void *__libc_malloc(size_t);
extern void *__libc_calloc(size_t,size_t);
extern void *__libc_realloc(void *,size_t);
extern void __libc_free(void *);
extern void *__libc_memalign(size_t,size_t);

typedef uint32_t index_t;
struct entry { uintptr_t pointer; size_t bytes; index_t left,right,height; };
struct counts {
    struct entry *table;
    size_t capacity,current,peak,allocated,allocations,probes;
    size_t entries,peak_entries,deletions,rotations,max_depth,next_unused;
    index_t root,free_head;
    int active,failed,failure_kind;
    uint64_t event_hash;
};
static __thread struct counts state,last;
static void event(uint64_t kind,size_t bytes) {
    uint64_t words[2]={kind,(uint64_t)bytes};
    for(size_t w=0;w<2;++w) for(size_t b=0;b<8;++b) {
        state.event_hash^=(words[w]>>(8*b))&255;
        state.event_hash*=UINT64_C(0x100000001b3);
    }
}
/* 1 live capacity, 2 arithmetic/accounting, 3 depth, 4 duplicate, 5 nested. */
static void fail(int kind) { state.failed=1;state.failure_kind=kind; }
static int visit(size_t depth) {
    ++state.probes;
    if(depth>state.max_depth) state.max_depth=depth;
    if(depth>64) { fail(3);return 0; }
    return 1;
}
static index_t height(index_t at) { return at ? state.table[at].height : 0; }
static void update(index_t at) {
    index_t a=height(state.table[at].left),b=height(state.table[at].right);
    state.table[at].height=1+(a>b?a:b);
}
static index_t right(index_t at) {
    index_t top=state.table[at].left;
    state.table[at].left=state.table[top].right;
    state.table[top].right=at;
    update(at);update(top);++state.rotations;return top;
}
static index_t left(index_t at) {
    index_t top=state.table[at].right;
    state.table[at].right=state.table[top].left;
    state.table[top].left=at;
    update(at);update(top);++state.rotations;return top;
}
static index_t balance(index_t at) {
    update(at);
    int d=(int)height(state.table[at].left)-(int)height(state.table[at].right);
    if(d>1) {
        index_t child=state.table[at].left;
        if(height(state.table[child].left)<height(state.table[child].right))
            state.table[at].left=left(child);
        return right(at);
    }
    if(d< -1) {
        index_t child=state.table[at].right;
        if(height(state.table[child].right)<height(state.table[child].left))
            state.table[at].right=right(child);
        return left(at);
    }
    return at;
}
static index_t find(uintptr_t pointer) {
    index_t at=state.root;
    size_t depth=1;
    while(at) {
        if(!visit(depth++)) return 0;
        if(pointer==state.table[at].pointer) return at;
        at=pointer<state.table[at].pointer ? state.table[at].left : state.table[at].right;
    }
    return 0;
}
static index_t insert(index_t at,index_t value,size_t depth) {
    if(!visit(depth)) return at;
    if(!at) return value;
    if(state.table[value].pointer<state.table[at].pointer)
        state.table[at].left=insert(state.table[at].left,value,depth+1);
    else state.table[at].right=insert(state.table[at].right,value,depth+1);
    return state.failed ? at : balance(at);
}
static void retire(index_t at) {
    state.table[at]=(struct entry){.left=state.free_head};state.free_head=at;
}
static index_t erase(index_t at,uintptr_t pointer,size_t depth) {
    if(!at || !visit(depth)) return at;
    if(pointer<state.table[at].pointer)
        state.table[at].left=erase(state.table[at].left,pointer,depth+1);
    else if(pointer>state.table[at].pointer)
        state.table[at].right=erase(state.table[at].right,pointer,depth+1);
    else {
        if(!state.table[at].left || !state.table[at].right) {
            index_t child=state.table[at].left ? state.table[at].left : state.table[at].right;
            retire(at);return child;
        }
        index_t next=state.table[at].right;
        size_t next_depth=depth+1;
        while(state.table[next].left) {
            if(!visit(next_depth++)) return at;
            next=state.table[next].left;
        }
        state.table[at].pointer=state.table[next].pointer;
        state.table[at].bytes=state.table[next].bytes;
        state.table[at].right=erase(state.table[at].right,state.table[next].pointer,depth+1);
    }
    return state.failed ? at : balance(at);
}
static index_t reserve(void) {
    index_t at=state.free_head;
    if(at) state.free_head=state.table[at].left;
    else {
        if(state.next_unused>state.capacity) { fail(1);return 0; }
        at=(index_t)state.next_unused++;
    }
    return at;
}
static void added(void *pointer,size_t bytes) {
    if(!pointer || !state.active || state.failed) return;
    if(find((uintptr_t)pointer)) { fail(4);return; }
    if(state.failed) return;
    if(bytes>SIZE_MAX-state.current || bytes>SIZE_MAX-state.allocated || state.allocations==SIZE_MAX) { fail(2);return; }
    index_t at=reserve();if(!at) return;
    state.table[at]=(struct entry){.pointer=(uintptr_t)pointer,.bytes=bytes,.height=1};
    state.root=insert(state.root,at,1);if(state.failed) return;
    event(1,bytes);
    state.current+=bytes;state.allocated+=bytes;++state.allocations;++state.entries;
    if(state.current>state.peak) state.peak=state.current;
    if(state.entries>state.peak_entries) state.peak_entries=state.entries;
}
static void removed(uintptr_t pointer) {
    if(!pointer || !state.active || state.failed) return;
    index_t at=find(pointer);if(!at || state.failed) return;
    if(state.table[at].bytes>state.current || state.entries==0) { fail(2);return; }
    event(2,state.table[at].bytes);
    state.current-=state.table[at].bytes;--state.entries;++state.deletions;
    state.root=erase(state.root,pointer,1);
}

void *malloc(size_t bytes) {
    void *pointer = __libc_malloc(bytes);
    added(pointer, bytes);
    return pointer;
}
void *calloc(size_t count, size_t width) {
    void *pointer = __libc_calloc(count, width);
    if (pointer) {
        if (width != 0 && count > SIZE_MAX / width) state.failed = state.active;
        else added(pointer, count * width);
    }
    return pointer;
}
void free(void *pointer) { removed((uintptr_t)pointer); __libc_free(pointer); }
void *realloc(void *pointer, size_t bytes) {
    /* Preserve old accounting on allocation failure. Updating after realloc
     * means the peak is simultaneous requested storage, not allocation churn. */
    uintptr_t address = (uintptr_t)pointer;
    void *result = __libc_realloc(pointer, bytes);
    if (result || bytes == 0) { removed(address); added(result, bytes); }
    return result;
}
void *memalign(size_t alignment, size_t bytes) {
    void *pointer = __libc_memalign(alignment, bytes);
    added(pointer, bytes);
    return pointer;
}
void *aligned_alloc(size_t alignment, size_t bytes) { return memalign(alignment, bytes); }
int posix_memalign(void **result, size_t alignment, size_t bytes) {
    if (alignment < sizeof(void *) || (alignment & (alignment - 1)) != 0) return EINVAL;
    int saved = errno;
    void *pointer = memalign(alignment, bytes);
    if (!pointer) { errno = saved; return ENOMEM; }
    *result = pointer;
    errno = saved;
    return 0;
}


int nts_counter_begin_capacity(size_t capacity) {
    if(state.active) { fail(5);return 1; }
    if(capacity<16 || (capacity&(capacity-1)) || capacity>=UINT32_MAX || capacity>SIZE_MAX/sizeof(struct entry)-1) return 1;
    if(state.table) munmap(state.table,(state.capacity+1)*sizeof(struct entry));
    memset(&state,0,sizeof(state));state.capacity=capacity;state.next_unused=1;
    state.table=mmap(NULL,(capacity+1)*sizeof(struct entry),PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0);
    if(state.table==MAP_FAILED) {state.table=NULL;return 1;}
    state.event_hash=UINT64_C(0xcbf29ce484222325);state.active=1;return 0;
}
int nts_counter_begin(void) {return nts_counter_begin_capacity((size_t)1<<22);}
int nts_counter_end(void) {if(!state.active) return 1;state.active=0;last=state;return state.failed;}
size_t nts_counter_current(void) {return state.current;}
size_t nts_counter_peak(void) {return last.peak;}
size_t nts_counter_live(void) {return last.current;}
size_t nts_counter_allocated(void) {return last.allocated;}
size_t nts_counter_allocations(void) {return last.allocations;}
size_t nts_counter_probes(void) {return last.probes;}
size_t nts_counter_entries(void) {return last.entries;}
size_t nts_counter_peak_entries(void) {return last.peak_entries;}
size_t nts_counter_deletions(void) {return last.deletions;}
size_t nts_counter_rotations(void) {return last.rotations;}
size_t nts_counter_max_depth(void) {return last.max_depth;}
size_t nts_counter_failure_kind(void) {return (size_t)last.failure_kind;}
size_t nts_counter_table_bytes(void) {return (last.capacity+1)*sizeof(struct entry);}

uint64_t nts_counter_event_hash(void) {return last.event_hash;}
